-- Map rework (November 2026): photos, menus and videos on spots, and a warning for places
-- whose gluten-free options share a kitchen with gluten. Keeps the doctors, replaces every other spot
-- with the places checked by the team.

alter table public.spots add column if not exists media jsonb not null default '[]'::jsonb;
alter table public.spots add column if not exists links jsonb not null default '[]'::jsonb;
alter table public.spots add column if not exists cross_contamination_risk boolean not null default false;

alter table public.spots
  add constraint spots_media_is_array check (jsonb_typeof(media) = 'array' and jsonb_typeof(links) = 'array');

delete from public.spots where category <> 'DOCTOR';

